/* LINKEDIN OUTREACH — the mid-month and day-30 reports (Build 5). 4 Nov 2026.
 *
 * CJ's brief: on launch + 14 days, "connection requests sent, InMails sent,
 * new connections, new conversations (replies), leads generated, plus the
 * list of lead names, for the period. One line from Claude summarizing what's
 * working"; on launch + 29 days "the same numbers for the full month, plus
 * two recommendations for next month generated by Claude from the reply
 * classifications". Every number is a SUM of Julie's daily rows and the
 * reply rows — never typed, never estimated. Pure except writeLines(). */

/** Reports due for the CURRENT month (period_start, which moves on 30 days
 * at each renewal). A report is written ON its due day and covers the period
 * up to the day before, so the last day's log is complete (3 Nov check).
 * `have` = kinds already written for this period. Pure. */
export function reportsDue(e, today, have = []) {
  const out = [];
  const start = e?.period_start || e?.launch_date;
  if (!start) return out;
  const dayBefore = (iso) => { const [y, m, d] = iso.split("-").map(Number); return new Date(Date.UTC(y, m - 1, d - 1)).toISOString().slice(0, 10); };
  if (e.midmonth_due && e.midmonth_due <= today && !have.includes("midmonth")) out.push({ kind: "midmonth", start, end: dayBefore(e.midmonth_due) });
  if (e.report_due && e.report_due <= today && !have.includes("day30")) out.push({ kind: "day30", start, end: dayBefore(e.report_due) });
  return out;
}

/** Totals for a period, inclusive. Leads come from classified replies, so
 * the old "Leads" column is never typed again. Pure. */
export function periodTotals(daily = [], replies = [], start, end) {
  const inside = (d) => d && d >= start && d <= end;
  const t = { connections_sent: 0, inmails: 0, accepted: 0, replies: 0, leads: 0, days_logged: 0 };
  for (const r of daily) {
    if (!inside(r.day)) continue;
    t.connections_sent += Number(r.connections_sent) || 0;
    t.inmails += Number(r.inmails) || 0;
    t.accepted += Number(r.accepted) || 0;
    t.replies += Number(r.replies) || 0;
    t.days_logged += 1;
  }
  const leads = replies.filter((r) => inside(r.day) && r.reply_status === "lead");
  t.leads = leads.length;
  return { totals: t, leadNames: leads.map((r) => r.name).filter(Boolean) };
}

/** Reply classifications counted, for the recommendations. Pure. */
export function classificationCounts(replies = [], start, end) {
  const out = {};
  for (const r of replies) if (r.day >= start && r.day <= end && r.classification) out[r.classification] = (out[r.classification] || 0) + 1;
  return out;
}

export function buildReportPrompt(kind, { company, totals, counts, lists = [] }) {
  return {
    system: "You write one or two short, plain lines for a LinkedIn outreach report to a business owner. Use ONLY the numbers given. Never invent numbers, names or causes. No hype. JSON only.",
    context: [
      `Business: ${company}`,
      `Report: ${kind === "midmonth" ? "first two weeks" : "first full month"}`,
      `Numbers: ${JSON.stringify(totals)}`,
      `Reply classifications: ${JSON.stringify(counts)}`,
      `Lists worked: ${lists.map((l) => l.campaign_title).filter(Boolean).join("; ") || "(not recorded)"}`,
      kind === "midmonth"
        ? 'Return {"summary":"one line on what is working, inviting list or messaging adjustments"}'
        : 'Return {"summary":"one line","recommendations":["first recommendation for next month","second recommendation"]}',
    ].join("\n"),
  };
}

export function parseReportLines(raw, kind) {
  const text = String(raw || "").replace(/```(?:json)?/gi, "");
  const a = text.indexOf("{"); const b = text.lastIndexOf("}");
  try {
    const o = JSON.parse(text.slice(a, b + 1));
    const recs = Array.isArray(o.recommendations) ? o.recommendations.map((x) => String(x).trim()).filter(Boolean).slice(0, 2) : [];
    return { ok: Boolean(String(o.summary || "").trim()), summary: String(o.summary || "").trim().slice(0, 400), recommendations: kind === "day30" ? recs : [] };
  } catch { return { ok: false, summary: "", recommendations: [] }; }
}

/** The report email (plain text). Wording is ours — the brief's "Resources
 * workbook" templates weren't available (asked CJ, 4 Nov 2026). Pure. */
/* Wording from CJ's Resources file, sheet "Report" (4 Nov 2026): the same
 * five lines in the same order, "Results Generated DATE - DATE", and the
 * end-of-month version. "I" becomes "we" because the team signs it, and
 * "billing renewing tomorrow" is left out: Stripe renews from the payment
 * date, not the launch date. */
export function reportEmail(kind, { contactName, company, start, end, totals, leadNames, summary, recommendations }) {
  const first = String(contactName || "").trim().split(/\s+/)[0] || "there";
  const mid = kind === "midmonth";
  const lines = [
    `Hello ${first},`,
    "",
    mid
      ? "Hope all is well! We wanted to touch base to provide you with your mid-month report. See below to review a breakdown of activity over the past two weeks:"
      : "Hope all is well on your side! We wanted to touch base as we wrap up the month and provide you with a recap of efforts over the past month. See below for more:",
    "",
    `Results Generated ${start} - ${end}`,
    "",
    `${totals.connections_sent} Connection Requests Sent`,
    `${totals.inmails} InMail Sent`,
    `${totals.accepted} New Connections Made`,
    `${totals.replies} New Conversations Generated`,
    `${totals.leads} Leads Generated${leadNames.length ? ` (${leadNames.join(", ")})` : ""}`,
    "",
    summary || "",
  ];
  if (!mid && recommendations?.length) lines.push("", "As we move into the next month, we'd recommend the following:", "", ...recommendations.map((r) => `\u2022 ${r}`));
  lines.push("", mid
    ? "Let us know your thoughts on efforts thus far whenever you have a moment and if you'd like to go ahead and make any adjustments to our lead list and or messaging sequence!"
    : "Beyond this, please share your thoughts/feedback whenever you have a moment. Happy to make additional changes to our messaging and or targeting if you'd like!",
    "", "Talk more soon,", "The AI Syndicate team");
  return { subject: `${mid ? "Mid-month report" : "Monthly recap"}: LinkedIn outreach for ${company}`, text: lines.filter((l, i, arr) => !(l === "" && arr[i - 1] === "")).join("\n") };
}
